styles.css:
html,body{margin:0;padding:0;background:#ECEFF2;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",Arial,sans-serif;}
.preview{max-width:677px;margin:0 auto;background:#fff;min-height:100vh;box-shadow:0 0 20px rgba(0,0,0,.06);}
#js_content{padding:24px 18px 40px;box-sizing:border-box;font-style:normal;font-weight:400;text-align:justify;font-size:16px;color:#3E3E3E;}
@media(max-width:640px){#js_content{padding:18px 14px 32px;}}

